package dev.pocketrun.update

import org.json.JSONObject

/** A published release and the one file the app installs from it. */
data class ReleaseInfo(
    val tag: String,
    val version: String,
    val notes: String,
    val asset: Asset,
) {
    data class Asset(val name: String, val url: String, val size: Long)
}

/**
 * Reading a GitHub release and deciding whether it is newer than the build that
 * is running. No Android and no networking here on purpose: this is the part
 * that has to be right, so it is the part that is unit-tested.
 */
object AppUpdate {

    /** The asset an install comes from; the debug one is a different app id. */
    const val APK_SUFFIX = "-release.apk"

    class ParseException(message: String) : Exception(message)

    fun parse(json: String): ReleaseInfo {
        val release = try {
            JSONObject(json)
        } catch (e: Exception) {
            throw ParseException("ответ GitHub не разобран")
        }
        if (release.optBoolean("draft")) throw ParseException("релиз помечен как черновик")
        val tag = release.optString("tag_name").ifBlank {
            throw ParseException("в релизе нет тега")
        }
        val assets = release.optJSONArray("assets")
            ?: throw ParseException("в релизе нет вложений")
        var chosen: JSONObject? = null
        for (i in 0 until assets.length()) {
            val asset = assets.optJSONObject(i) ?: continue
            val name = asset.optString("name")
            if (!name.endsWith(".apk")) continue
            if (name.endsWith(APK_SUFFIX)) {
                chosen = asset
                break
            }
            // A release whose file is named differently is still installable;
            // a debug build is not, it is a separate app.
            if (chosen == null && !name.contains("debug")) chosen = asset
        }
        val asset = chosen ?: throw ParseException("в релизе нет APK для установки")
        val url = asset.optString("browser_download_url").ifBlank { asset.optString("url") }
        if (url.isBlank()) throw ParseException("у APK в релизе нет ссылки")
        return ReleaseInfo(
            tag = tag,
            version = version(tag),
            notes = release.optString("body").trim(),
            asset = ReleaseInfo.Asset(
                name = asset.optString("name"),
                url = url,
                size = asset.optLong("size", 0L),
            ),
        )
    }

    /**
     * The version a tag names: `v1.5.0` and `1.5.0-debug` are both `1.5.0`. The
     * build's own versionName comes from the nearest tag (build.gradle.kts), so
     * comparing the two needs nothing but this.
     */
    fun version(tag: String): String = tag.trim()
        .removePrefix("v")
        .removePrefix("V")
        .substringBefore('-')
        .substringBefore('+')
        .trim()

    /**
     * True when [candidate] is strictly newer than [installed]. A prerelease
     * suffix (`-rc1`) is not read as a number and does not make anything newer
     * than the release it precedes; GitHub keeps prereleases out of /latest
     * anyway.
     */
    fun isNewer(candidate: String, installed: String): Boolean {
        val left = parts(candidate)
        val right = parts(installed)
        val size = maxOf(left.size, right.size)
        for (i in 0 until size) {
            val a = left.getOrElse(i) { 0L }
            val b = right.getOrElse(i) { 0L }
            if (a != b) return a > b
        }
        return false
    }

    private fun parts(version: String): List<Long> = version.split('.')
        .map { it.takeWhile(Char::isDigit) }
        .map { if (it.isEmpty()) 0L else it.toLong() }
}

package dev.pocketrun.update

import java.io.File
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL

/**
 * Fetches the newest release from GitHub and downloads its APK.
 *
 * The repository is public, so this works without a token; a configured one is
 * sent anyway, which raises the API rate limit for someone who set it up for
 * the agent.
 */
class AppUpdater(private val repo: String, private val token: String = "") {

    class UpdateException(message: String) : IOException(message)

    /** The newest published release. Throws [UpdateException] with a readable reason. */
    fun latest(): ReleaseInfo {
        val body = try {
            read(URL("$API/repos/$repo/releases/latest"), "application/vnd.github+json")
        } catch (e: UpdateException) {
            throw e
        } catch (e: Exception) {
            throw UpdateException("GitHub недоступен: ${e.message ?: e.javaClass.simpleName}")
        }
        return try {
            AppUpdate.parse(body)
        } catch (e: AppUpdate.ParseException) {
            throw UpdateException(e.message ?: "релиз не разобран")
        }
    }

    /**
     * Downloads [url] to [target] through a `.part` file, so an interrupted
     * download is never mistaken for a finished one. [onProgress] gets
     * (downloaded, total); total is 0 when the server did not say.
     */
    fun download(url: String, target: File, onProgress: (Long, Long) -> Unit): File {
        target.parentFile?.mkdirs()
        val partial = File(target.parentFile, target.name + ".part")
        partial.delete()
        target.delete()
        val connection = try {
            open(url, "application/octet-stream")
        } catch (e: Exception) {
            throw UpdateException("не удалось начать загрузку: ${e.message ?: e.javaClass.simpleName}")
        }
        try {
            val total = connection.contentLengthLong
            if (total > MAX_APK_BYTES) {
                throw UpdateException("файл больше, чем приложение готово скачать")
            }
            var done = 0L
            connection.inputStream.use { input ->
                partial.outputStream().buffered().use { output ->
                    val buffer = ByteArray(64 * 1024)
                    while (true) {
                        val read = input.read(buffer)
                        if (read < 0) break
                        output.write(buffer, 0, read)
                        done += read
                        onProgress(done, if (total > 0) total else 0L)
                    }
                }
            }
            if (total > 0 && done != total) throw UpdateException("загрузка не завершена")
            if (!partial.renameTo(target)) {
                throw UpdateException("не удалось сохранить файл")
            }
            return target
        } catch (e: UpdateException) {
            partial.delete()
            throw e
        } catch (e: Exception) {
            partial.delete()
            throw UpdateException("загрузка не удалась: ${e.message ?: e.javaClass.simpleName}")
        } finally {
            connection.disconnect()
        }
    }

    private fun read(url: URL, accept: String): String {
        val connection = open(url, accept)
        try {
            val status = connection.responseCode
            if (status != 200) {
                throw UpdateException(
                    when (status) {
                        404 -> "релиз не найден: $repo"
                        403, 429 -> "GitHub не отдаёт релиз (лимит запросов)"
                        else -> "GitHub ответил HTTP $status"
                    },
                )
            }
            return connection.inputStream.bufferedReader().readText()
        } finally {
            connection.disconnect()
        }
    }

    private fun open(url: URL, accept: String): HttpURLConnection =
        (url.openConnection() as HttpURLConnection).apply {
            requestMethod = "GET"
            connectTimeout = 20_000
            readTimeout = 60_000
            instanceFollowRedirects = true
            setRequestProperty("Accept", accept)
            setRequestProperty("User-Agent", USER_AGENT)
            setRequestProperty("X-GitHub-Api-Version", "2022-11-28")
            if (token.isNotBlank()) setRequestProperty("Authorization", "Bearer $token")
        }

    companion object {
        private const val API = "https://api.github.com"
        private const val USER_AGENT = "PocketRun-Updater"
        private const val MAX_APK_BYTES = 512L * 1024 * 1024
    }
}

